// Cloudflare entrypoint: HTTP goes to the OpenNext handler, and the four-hour
// cron calls back into the app to run Ada's research pass.
// @ts-ignore generated by the OpenNext Cloudflare build
import { default as openNextWorker } from "./.open-next/worker.js";

type TenantEnv = {
  CRON_SECRET?: string;
  DEEPSEEK_API_KEY?: string;
};

type WorkerContext = { waitUntil: (promise: Promise<unknown>) => void };
type ScheduledEvent = { scheduledTime: number; cron?: string };

type OpenNextHandler = {
  fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response>;
};

const handler = openNextWorker as unknown as OpenNextHandler;

const invokeApp = (path: string, body: unknown, env: TenantEnv, context: WorkerContext) =>
  handler.fetch(
    new Request(`https://alaguillotine-internal.invalid${path}`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${env.CRON_SECRET ?? ""}`,
        "content-type": "application/json",
      },
      body: JSON.stringify(body),
    }),
    env,
    context,
  );

export default {
  fetch: (request: Request, env: TenantEnv, context: WorkerContext) =>
    handler.fetch(request, env, context),

  scheduled(event: ScheduledEvent, env: TenantEnv, context: WorkerContext) {
    if (!env.CRON_SECRET) {
      console.error("clock_cron_misconfigured");
      return;
    }
    // One scrape, four hours apart. The page fakes the liveness, not the bill.
    const paths =
      event.cron === "30 */12 * * *"
        ? ["/api/clock/refresh", "/api/hateometer/refresh", "/api/posts/refresh", "/api/manifesto/refresh"]
        : ["/api/clock/refresh"];

    for (const path of paths) {
      context.waitUntil(
        invokeApp(path, { scheduledTime: event.scheduledTime }, env, context).then((response) => {
          if (!response.ok) {
            throw new Error(`${path} returned HTTP ${response.status}.`);
          }
        }),
      );
    }
  },
};

// The OpenNext adapter may depend on these named handlers for its internal cache.
// @ts-ignore generated by the OpenNext Cloudflare build
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
